#include "Classifier.h"
#include "ap_int.h"
#include "Exp.h"
#include "bias.h"

// Split headers generated by the script below
#include "svs_0_p800.h"
#include "svs_1_p800.h"
#include "alphas_0_padded.h"
#include "alphas_1_padded.h"
#include "sv_norms_0_padded.h"
#include "sv_norms_1_padded.h"

static const int LANES     = 16;
//static const int PIX_U     = 16;
//static const int PIX_GROUP = IMG_SIZE / PIX_U;     // 49
static const int RECON_U   = 4;                    // unroll reconstruct
static const int NSV0      = 96;                   // padded
static const int NSV1      = 96;                   // padded
static const int PIX_U     = 16;
static const int PIX_GROUP = IMG_SIZE / PIX_U;  // 784/16 = 49
static const int IMG_PAD = 800;


ap_fixed<24,14> load_and_calc_norm(
    hls::stream<axis_t> &in_stream,
    ap_fixed<8,7> x_local[IMG_PAD],
    ap_uint<6> active_groups[PIX_GROUP],
    ap_uint<6> &active_count

) {
#pragma HLS INLINE off

    ap_fixed<24,14> calculated_norm = 0;
    ap_uint<PIX_GROUP> seen = 0;
    active_count = 0;

    for (int i = 0; i < IMG_SIZE/8; i++) {   // 98 reads, matches TB
    #pragma HLS PIPELINE II=1
        axis_t packet = in_stream.read();
        ap_uint<64> data = packet.data;

        // group index must match PIX_U
        // PIX_U=16 => 2 packets per group => i>>1
        ap_uint<6> g = (ap_uint<6>)(i >> 1);

        bool any_nz = false;

        for (int p = 0; p < 8; p++) {
    #pragma HLS UNROLL
            ap_fixed<8,7> val;
            val(7,0) = data.range((p<<3)+7, (p<<3));

            int idx = (i<<3) + p;
            x_local[idx] = val;

            ap_fixed<16,14> sq;
            #pragma HLS RESOURCE variable=sq core=DSP48
            sq = val * val;
            calculated_norm += sq;

            any_nz |= (val != ap_fixed<8,7>(0));
        }

        if (any_nz && !seen[g]) {
            seen[g] = 1;
            active_groups[active_count] = g;
            active_count++;
        }
    }

    // pad the extra [784..799]
    pad_tail: for (int j = IMG_SIZE; j < IMG_PAD; j++) {
    #pragma HLS UNROLL
        x_local[j] = 0;
    }

    return calculated_norm;
}


void compute_and_output(ap_fixed<8,7> x_local[IMG_PAD],
                        ap_fixed<24,14> x_norm_in,
                        const ap_uint<6> active_groups[PIX_GROUP],
                        ap_uint<6> active_count,
                        hls::stream<result_pkt> &out_stream,
                        int n, int num_images) {
#pragma HLS INLINE off
#pragma HLS RESOURCE variable=svs_0_p800 core=ROM_2P_BRAM
#pragma HLS RESOURCE variable=svs_1_p800 core=ROM_2P_BRAM


    // Two machines
    ap_fixed<32,16> partial_sum[2][LANES];
#pragma HLS ARRAY_PARTITION variable=partial_sum complete dim=1
#pragma HLS ARRAY_PARTITION variable=partial_sum complete dim=2

    // init
    for (int m=0; m<2; m++) {
#pragma HLS UNROLL
        for (int k=0; k<LANES; k++) {
#pragma HLS UNROLL
            partial_sum[m][k] = 0;
        }
    }

    // Iterate batches for each machine (both have same padded length)
    for (int i = 0; i < NSV0; i += LANES) {
#pragma HLS LOOP_TRIPCOUNT min=6 max=6 avg=6

        ap_fixed<32,16> dot[2][LANES];
#pragma HLS ARRAY_PARTITION variable=dot complete dim=1
#pragma HLS ARRAY_PARTITION variable=dot complete dim=2

        for (int m=0; m<2; m++) {
#pragma HLS UNROLL
            for (int k=0; k<LANES; k++) {
#pragma HLS UNROLL
                dot[m][k] = 0;
            }
        }

        // Dot products over 16-pixel groups
        for (int t = 0; t < (int)active_count; t++) {
        #pragma HLS LOOP_TRIPCOUNT min=1 max=49 avg=15
        #pragma HLS PIPELINE II=1

            ap_uint<6> jg = active_groups[t];

            ap_fixed<8,7> xpix[PIX_U];
        #pragma HLS ARRAY_PARTITION variable=xpix complete dim=1
            for (int p=0; p<PIX_U; p++) {
        #pragma HLS UNROLL
                xpix[p] = x_local[jg*PIX_U + p];
            }

            for (int m=0; m<2; m++) {
        #pragma HLS UNROLL
                for (int k=0; k<LANES; k++) {
        #pragma HLS UNROLL
                    ap_fixed<32,16> sum_pix = 0;
                    for (int p=0; p<PIX_U; p++) {
        #pragma HLS UNROLL
                        ap_fixed<8,7> xi =
                            (m==0) ? svs_0_p800[i+k][jg*PIX_U + p]
                                   : svs_1_p800[i+k][jg*PIX_U + p];
                        ap_fixed<16,14> prod;
                        #pragma HLS RESOURCE variable=prod core=DSP48
                        prod = xi * xpix[p];
                        sum_pix += prod;
                    }
                    dot[m][k] += sum_pix;
                }
            }
        }


        // Reconstruct + exp + alpha*K
        // Do 4 lanes per cycle (RECON_U)
        for (int kk = 0; kk < LANES; kk += RECON_U) {
#pragma HLS LOOP_TRIPCOUNT min=4 max=4 avg=4
#pragma HLS PIPELINE II=1

            for (int m=0; m<2; m++) {
#pragma HLS UNROLL
                for (int r=0; r<RECON_U; r++) {
#pragma HLS UNROLL
                    int k = kk + r;

                    ap_fixed<32,16> svn =
                        (m==0) ? sv_norms_0_padded[i+k] : sv_norms_1_padded[i+k];
                    ap_fixed<32,16> alpha =
                        (m==0) ? ap_fixed<32,16>(alphas_0_padded[i+k])
                               : ap_fixed<32,16>(alphas_1_padded[i+k]);

                    ap_fixed<32,16> dist_sq =
                        ap_fixed<32,16>(x_norm_in) + svn - (dot[m][k] << 1);

                    if (dist_sq < 0) dist_sq = 0;

                    ap_fixed<22,1> K = (ap_fixed<22,1>)compute_exp(-(dist_sq >> 10));
                    partial_sum[m][k] += alpha * ap_fixed<32,16>(K);
                }
            }
        }
    }

    ap_fixed<32,16> sum = 0;
    for (int m=0; m<2; m++) {
#pragma HLS UNROLL
        for (int k=0; k<LANES; k++) {
#pragma HLS UNROLL
            sum += partial_sum[m][k];
        }
    }

    result_pkt out_val;
    out_val.data = (ap_fixed<32,16>)(sum + bias[0]);
    out_val.keep = -1;
    out_val.strb = -1;
    out_val.last = (n == num_images - 1) ? 1 : 0;
    out_stream.write(out_val);

}

void classify(hls::stream<axis_t> &in_stream,
              hls::stream<result_pkt> &out_stream,
              int num_images) {
#pragma HLS INTERFACE axis port=in_stream
#pragma HLS INTERFACE axis port=out_stream
#pragma HLS INTERFACE s_axilite port=num_images bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Each split SV array needs the same banking as your original
#pragma HLS ARRAY_RESHAPE   variable=svs_0_p800 cyclic factor=PIX_U dim=2  // PIX_U=32
#pragma HLS ARRAY_PARTITION variable=svs_0_p800 cyclic factor=LANES dim=1
#pragma HLS ARRAY_RESHAPE   variable=svs_1_p800 cyclic factor=PIX_U dim=2
#pragma HLS ARRAY_PARTITION variable=svs_1_p800 cyclic factor=LANES dim=1



#pragma HLS ARRAY_PARTITION variable=alphas_0_padded cyclic factor=LANES dim=1
#pragma HLS ARRAY_PARTITION variable=alphas_1_padded cyclic factor=LANES dim=1
#pragma HLS ARRAY_PARTITION variable=sv_norms_0_padded cyclic factor=LANES dim=1
#pragma HLS ARRAY_PARTITION variable=sv_norms_1_padded cyclic factor=LANES dim=1



    Batch_Loop: for (int n = 0; n < num_images; n++) {
#pragma HLS LOOP_TRIPCOUNT min=2601 max=2601 avg=2601
#pragma HLS DATAFLOW
        ap_fixed<8,7> x_local[IMG_PAD];
#pragma HLS ARRAY_PARTITION variable=x_local cyclic factor=PIX_U dim=1 // 32 banks


        ap_uint<6> active_groups[PIX_GROUP];
        #pragma HLS ARRAY_PARTITION variable=active_groups complete dim=1
        ap_uint<6> active_count;
        ap_fixed<24,14> internal_norm =
        load_and_calc_norm(in_stream, x_local, active_groups, active_count);
        compute_and_output(x_local, internal_norm, active_groups, active_count,
        out_stream, n, num_images);

    }
}
